param([Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][string]$RomPath)
$ErrorActionPreference='Stop';$target="$PSScriptRoot/../evidence/mpu4/skill-cash";if((Get-Content "$RunDirectory/exit-code.txt" -Raw).Trim() -ne '0'){throw 'Capture incomplete'};if((Get-FileHash $RomPath -Algorithm SHA1).Hash -ne '402D1518BB78FDC489B06C2AABC771E5CE151847'){throw 'Unexpected ROM'}
$reference=Get-Content "$target/pia-service-timing-verification.json" -Raw|ConvertFrom-Json;if((Get-FileHash "$RunDirectory/ptm-skill-cpu.csv").Hash -ne $reference.phase_sha256){throw 'Passive guard observation changed354 timer samples'}
$cpuProof=Get-Content "$target/cpu-interrupts-verification.json" -Raw|ConvertFrom-Json;$raw="$($cpuProof.run_directory)/debug.log";if((Get-FileHash $raw).Hash -ne $cpuProof.raw_debug_sha256){throw 'Original IRQ evidence changed'}
$expected=[Collections.Generic.List[ulong]]::new();$entry=0UL;foreach($line in [IO.File]::ReadLines($raw)){if($line -match '^IE cycle=([0-9A-F]+)'){$entry=[Convert]::ToUInt64($Matches[1],16)};if($line -match '^MS cycle=([0-9A-F]+)'){if([Convert]::ToUInt64($Matches[1],16)-$entry -eq 112){$expected.Add($entry)}}}
$records=@(Import-Csv "$RunDirectory/timer1-swi2.csv");if($records.Count -ne 60 -or $expected.Count -ne 60){throw 'Expected60 natural timer1 SWI2 returns'}
$rows=@(for($i=0;$i -lt $records.Count;$i++){$r=$records[$i];$cycle=[ulong][decimal]::Round(([decimal]$r.seconds*1000000000000000000d+[decimal]$r.attoseconds)*1720000d/1000000000000000000d)-1;$u=[Convert]::ToInt32($r.savedu,16);$signed=if($u -ge 32768){$u-65536}else{$u};if($cycle -ne $expected[$i]+77 -or $r.returnpc -ne 'FEB7' -or $r.option -ne '00' -or $r.savedu -ne $r.registeru -or $signed -ge 0x525){throw "Natural guard differs at$i"};[ordered]@{handler_cycle=$expected[$i];vector_cycle=$cycle;saved_u=$u;swi_saved_s=[Convert]::ToInt32($r.s,16);return_pc=0xFEB7;option=0;generated_scan_cycle=$expected[$i]+112}})
[ordered]@{classification='Natural original full Skill Cash campaign, passive FE66 observer. All60 ignored SWI2 returns match independently retained112-cycle entry-to-scan observations.354 original timer samples unchanged. Saved U and SWI return frame observed without hardware-register reads.';rows=$rows}|ConvertTo-Json -Depth 5|Set-Content "$target/timer1-guard-timing.json"
[ordered]@{source_run=$RunDirectory;csv_sha256=(Get-FileHash "$RunDirectory/timer1-swi2.csv").Hash;lua_sha256=(Get-FileHash "$RunDirectory/ptm-skill-cpu.lua").Hash;phase_sha256=(Get-FileHash "$RunDirectory/ptm-skill-cpu.csv").Hash;original_irq_debug_sha256=$cpuProof.raw_debug_sha256;rom_sha1=(Get-FileHash $RomPath -Algorithm SHA1).Hash;provenance=(Get-Content "$RunDirectory/provenance.json" -Raw|ConvertFrom-Json);guards=$records.Count}|ConvertTo-Json -Depth 6|Set-Content "$target/timer1-guard-timing-verification.json"
Write-Output 'Curated60 natural ignored timer1 SWI2 returns'
